#!/usr/bin/env node
// check-docs-drift.mjs — fail-closed reconcile of committed docs against their
// code source-of-truth. Catches two doc-drift surfaces that previously shipped
// without a gate:
//
//   A. assets/demo.svg  vs  `node dist/cli.js --demo`
//      The README hero SVG is generated by scripts/render-demo-svg.mjs. Nothing
//      re-rendered it on rule changes, so it could silently staleen. This regens
//      into a scratch copy and byte-compares — the working tree is left untouched.
//
//   B. Stripe API version literal  vs  the CLI's own --version
//      `2026-06-24.dahlia` is hand-duplicated ~40x across README / COVERAGE /
//      CHANGELOG; the real value is STRIPE_API_VERSION (src/stripe-client.ts),
//      surfaced at runtime by `stripe-audit -v`. When the SDK pin bumps, every
//      doc copy must move with it. Any api-version-shaped literal that does not
//      equal the canonical one is drift.
//
// Requires a built dist/ (run `npm run build` first). Exits non-zero on any drift
// with an actionable fix line. Side-effect-free: it never leaves a modified tree.
//
// Usage:  npm run check:docs   (or: node scripts/check-docs-drift.mjs)

import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join, relative } from 'node:path'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const CLI = join(ROOT, 'dist', 'cli.js')
const RENDER = join(ROOT, 'scripts', 'render-demo-svg.mjs')
const DEMO_SVG = join(ROOT, 'assets', 'demo.svg')
const RULES_MD = join(ROOT, 'docs', 'rules.md')
const API_DOCS = ['README.md', 'COVERAGE.md', 'CHANGELOG.md']

// An api-version literal in either plain (`2026-06-24.dahlia`) or shields-escaped
// (`2026--06--24.dahlia`) form. The channel suffix is alphanumeric.
const API_LITERAL = /\b\d{4}--?\d{2}--?\d{2}\.[a-z0-9]+\b/gi
const normalize = (s) => s.replace(/--/g, '-')

// A rule-ID token: SCREAMING_SNAKE, underscore REQUIRED. Requiring
// an underscore excludes non-rule ALL-CAPS (README/COVERAGE/CHANGELOG link text,
// column headers ID/SCOPE/CATEGORY/SEVERITY, prose acronyms) so rules.md can carry
// cross-links and prose without breaking the exact-match reconcile — while still
// pinning every real rule ID — the registry is all SCREAMING_SNAKE.
const RULE_ID = /[A-Z][A-Z0-9]*_[A-Z0-9_]+/g

const rel = (p) => relative(ROOT, p)
const failures = []

if (!existsSync(CLI)) {
  console.error(`✗ ${rel(CLI)} not found — run \`npm run build\` first.`)
  process.exit(1)
}

// ── Check A — assets/demo.svg is in sync with `--demo` ────────────────────────
function checkDemoSvg() {
  if (!existsSync(DEMO_SVG)) {
    failures.push(`${rel(DEMO_SVG)} is missing — run \`node scripts/render-demo-svg.mjs\`.`)
    return
  }
  const original = readFileSync(DEMO_SVG)
  try {
    // render-demo-svg.mjs writes DEMO_SVG in place; regenerate, compare, restore.
    execFileSync('node', [RENDER], { cwd: ROOT, stdio: 'pipe' })
    const regenerated = readFileSync(DEMO_SVG)
    if (!regenerated.equals(original)) {
      failures.push(
        `${rel(DEMO_SVG)} is stale vs \`--demo\` output — run ` +
          `\`node scripts/render-demo-svg.mjs\` and commit the result.`,
      )
    }
  } finally {
    writeFileSync(DEMO_SVG, original) // always leave the tree as we found it
  }
}

// ── Check B — every api-version literal matches the CLI's canonical version ────
function checkApiVersion() {
  const versionLine = execFileSync('node', [CLI, '-v'], { cwd: ROOT, encoding: 'utf8' })
  const canonical = versionLine.match(/Stripe API (\S+?)\)/)?.[1]
  if (!canonical) {
    failures.push(
      `could not parse the canonical Stripe API version from \`stripe-audit -v\` (got: ${versionLine.trim()})`,
    )
    return
  }

  let found = 0
  for (const name of API_DOCS) {
    const path = join(ROOT, name)
    if (!existsSync(path)) continue
    readFileSync(path, 'utf8')
      .split('\n')
      .forEach((line, i) => {
        for (const m of line.matchAll(API_LITERAL)) {
          found++
          if (normalize(m[0]) !== canonical) {
            failures.push(
              `${name}:${i + 1} — stale API version \`${m[0]}\` (canonical is ` +
                `\`${canonical}\` from \`stripe-audit -v\`).`,
            )
          }
        }
      })
  }
  if (found === 0) {
    failures.push(
      `no Stripe API-version literals found in ${API_DOCS.join(', ')} — the drift ` +
        `guard may be mis-targeted (docs restructured?). Expected the canonical ` +
        `\`${canonical}\` to appear.`,
    )
  }
}

// ── Check C — docs/rules.md rule IDs exactly match `--list-rules --output json` ──
// Promotes the CLI↔docs reconcile (was a one-time smoke check) to a standing
// gate, using the underscore-required token shape. Consumes the
// machine-readable `{ active, dropped }` JSON instead of scraping the
// human table, so layout changes to the human listing can never break this gate.
// DROPPED rules are part of the reconcile: the transparency promise is that
// every consciously-dropped rule is documented in rules.md alongside the active set.
function checkRuleCatalogue() {
  if (!existsSync(RULES_MD)) return // no catalogue in this project → nothing to reconcile
  const raw = execFileSync('node', [CLI, '--list-rules', '--output', 'json'], {
    cwd: ROOT,
    encoding: 'utf8',
  })
  let registry
  try {
    registry = JSON.parse(raw)
  } catch {
    failures.push('`stripe-audit --list-rules --output json` did not emit valid JSON.')
    return
  }
  const canonical = new Set(
    [...(registry.active ?? []), ...(registry.dropped ?? [])].map((r) => r.id),
  )
  if (canonical.size === 0) {
    failures.push(
      '`stripe-audit --list-rules --output json` produced no rule IDs — cannot reconcile docs/rules.md.',
    )
    return
  }

  // Invariant: every rule ID must contain `_`. A single-word rule ID
  // would be invisible to the underscore-required regex and silently un-guarded — so
  // assert it here against the authoritative registry rather than let it slip through.
  const noUnderscore = [...canonical].filter((id) => !id.includes('_'))
  if (noUnderscore.length > 0) {
    failures.push(
      `rule ID(s) without an underscore: ${noUnderscore.sort().join(', ')} — the underscore-` +
        `required reconcile regex can't see them. Revisit RULE_ID in this script.`,
    )
  }

  // Reconcile: the rules.md underscore-token set must EXACTLY equal the rule-ID set
  // (active ∪ dropped). Markdown link DESTINATIONS are stripped first so evidence
  // citations like `[verdict](verify-gates/RADAR_SETUP_INTENTS.md)` can't leak
  // filename tokens into the comparison — link TEXT still counts.
  const doc = readFileSync(RULES_MD, 'utf8').replace(/\]\([^)]*\)/g, ']()')
  const inDoc = new Set(doc.match(RULE_ID) ?? [])
  const missing = [...canonical].filter((id) => !inDoc.has(id))
  const extra = [...inDoc].filter((id) => !canonical.has(id))
  if (missing.length > 0) {
    failures.push(`docs/rules.md is missing rule ID(s): ${missing.sort().join(', ')}.`)
  }
  if (extra.length > 0) {
    failures.push(
      `docs/rules.md has SCREAMING_SNAKE token(s) that aren't rule IDs: ${extra.sort().join(', ')} ` +
        `— a typo'd/renamed rule ID, or all-caps prose (rewrite it lowercase).`,
    )
  }
}

checkDemoSvg()
checkApiVersion()
checkRuleCatalogue()

if (failures.length > 0) {
  console.error(
    `✗ docs-drift check failed (${failures.length} issue${failures.length === 1 ? '' : 's'}):`,
  )
  for (const f of failures) console.error(`  • ${f}`)
  process.exit(1)
}
console.log(
  '✓ docs in sync — demo.svg matches --demo, API-version literals canonical, rules.md ↔ --list-rules reconciled.',
)
